mapper.select:
SELECT *
  FROM payment_record
 WHERE patient_id = #{patientId}
 ORDER BY created_at DESC
 LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM payment_record
 WHERE patient_id = #{patientId}

SELECT pr.*, p.real_name AS patient_name, a.appointment_no FROM payment_record pr JOIN patient p ON p.id = pr.patient_id JOIN appointment a ON a.id = pr.appointment_id
WHERE pr.status = #{status}
ORDER BY pr.created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
  FROM payment_record

 WHERE status = #{status}
